INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (323974, 14165, 'South China Morning Post', 'en', 'What the Mecca military pact means for China', 'https://www.scmp.com/opinion/world-opinion/article/3363663/what-mecca-military-pact-means-china', 'When Saudi Crown Prince Mohammed bin Salman, Turkish President Recep Tayyip Erdogan, and Pakistani Prime Minister Shehbaz Sharif signed the Mecca defence agreement, they executed a structural overhaul of the Middle East’s security architecture. The pact codifies a defence commitment, where an armed attack on one is treated as an assault on all. Building upon September’s Saudi-Pakistan defence agreement, this tripartite arrangement bridges the financial capital of the Gulf, the...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/4898c01c-1c9c-41e2-a07b-d447fcf7cb24_e379e5a1.jpg?itok=ChZgc39W&v=1786587130', '2026-08-13T21:30:09+00:00', '2026-08-13T22:55:10.671478'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (324001, 14165, 'South China Morning Post', 'en', 'Saudi-Turkey-Pakistan Mecca pact ‘far from’ Nato-style defence alliance', 'https://www.scmp.com/news/china/diplomacy/article/3363871/saudi-turkey-pakistan-mecca-pact-falls-short-nato-style-defence-alliance', 'The security pact signed on Friday by three of the world’s most powerful Muslim nations with a vow to enhance collective deterrence remains far from what many are calling an Islamic Nato, according to experts. The Mecca Joint Defence Agreement between Saudi Arabia, the Persian Gulf’s top oil exporter, Nato member Turkey and Pakistan, a nuclear-armed South Asian state, would be challenged by diverging strategic interests and weak mutual defence capacity, they said. The Mecca pact’s statement that...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/ada9527d-57b6-47f6-b913-3852fadac73b_1bb61ffe.jpg?itok=_Q7rCdNL&v=1786600503', '2026-08-13T10:22:23+00:00', '2026-08-13T22:55:10.947092'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
