INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321701, 14172, 'The Economic Times', 'en', 'US stocks: Tapestry forecasts weak annual sales as Kate Spade struggles, shares tumble 15%', 'https://economictimes.indiatimes.com/markets/us-stocks/news/us-stocks-tapestry-forecasts-weak-annual-sales-as-kate-spade-struggles-shares-tumble-15/articleshow/133217828.cms', 'Tapestry has reported quarterly profits that surpass expectations despite a forecast of sluggish annual revenue growth. Kate Spade''s sales fell by seven percent, in stark contrast to Coach, which saw a robust fourteen percent increase. Meanwhile, growth in North American revenue slowed to seven percent as consumer spending remained cautious. However, international sales in China and Europe showed impressive growth, although Tapestry''s shares took a notable hit post-report.', 'https://img.etimg.com/photo/msid-133217828,imgsize-119212.cms', '2026-08-13T15:43:20+00:00', '2026-08-13T22:51:37.503853'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321704, 14172, 'The Economic Times', 'en', 'US stocks: Birkenstock shares jump 18% as strong demand prompts revenue forecast hike', 'https://economictimes.indiatimes.com/markets/us-stocks/news/birkenstock-raises-revenue-forecast-on-strong-demand-shares-jump-15/articleshow/133215222.cms', 'Birkenstock has raised its annual sales growth forecast after surpassing quarterly revenue expectations. The company''s robust performance was largely driven by strong full-price demand for its premium sandals. Sales through the direct-to-consumer channel surged by fourteen percent, accounting for nearly thirty-nine percent of total revenue. The Asia-Pacific region led the way in growth, while EMEA and the Americas also enjoyed robust double-digit increases.', 'https://img.etimg.com/photo/msid-133215222,imgsize-484238.cms', '2026-08-13T14:09:37+00:00', '2026-08-13T22:51:37.536825'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321708, 14172, 'The Economic Times', 'en', 'LG Electronics India Q1 Results: PAT rises 27% YoY to Rs 653 crore; revenue up 15%', 'https://economictimes.indiatimes.com/markets/stocks/earnings/lg-electronics-india-q1-results-pat-rises-marginally-to-rs-653-crore-revenue-up-15/articleshow/133212601.cms', 'LG Electronics India Q1 Results: Household appliances maker LG Electronics India reported a 27.2 % year-on-year rise in profit after tax (PAT) at Rs 653 crore for the first quarter of FY27 (Q1FY27), compared with Rs 513 crore reported in the same quarter of the previous fiscal year.', 'https://img.etimg.com/photo/msid-133212601,imgsize-120976.cms', '2026-08-13T12:53:37+00:00', '2026-08-13T22:51:37.580146'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
