INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (320924, 14191, 'The Guardian', 'en', 'Behind England’s bumper A-level results lie record levels of regional disparities', 'https://www.theguardian.com/education/2026/aug/13/england-a-level-results-record-levels-regional-disparities', 'Need for Burnham to tackle regional inequality could not be clearer as London becomes ‘educational outlier’ Andy Burnham has put regional inequality at the top of his agenda as prime minister, and nowhere is the need for doing so clearer than in education. As England’s A-level results were published on Thursday morning, students across the country were pictured celebrating a bumper crop of results, with record rates of As and A*s . Continue reading...', 'https://i.guim.co.uk/img/media/49b15fe071f35996a696db9bf87d62e17ca28699/1063_1_3203_2562/master/3203.jpg?width=140&quality=85&auto=format&fit=max&s=7729d12f691fa7aa4df20bcb7d951607', '2026-08-13T18:22:09+00:00', '2026-08-13T22:50:38.046172'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
