INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333426, 14191, 'The Guardian', 'en', 'Students squeezed out of university courses after bumper A-level grades', 'https://www.theguardian.com/education/2026/aug/14/students-squeezed-out-university-courses-bumper-crop-top-a-level-grades', 'Students narrowly missing grades are being rejected, while some on oversubscribed courses are asked to defer Students across the UK have found themselves unexpectedly squeezed out of their desired university courses as this year’s bumper crop of A-level grades ​h​as not always translated into ​​the places many were hoping for. ​With close to a third of the A-levels awarded in England, Wales and Northern Ireland achieving the top A and A* grades this year, universities are taking a tougher stance by rejecting students who narrowly missed their expected grades and who in previous years would sti', 'https://i.guim.co.uk/img/media/6249b834037458792f5c22cff3c149ac45f41166/965_0_5830_4666/master/5830.jpg?width=140&quality=85&auto=format&fit=max&s=784c217a388e29878aa259c4de9f9cbd', '2026-08-14T15:54:28+00:00', '2026-08-14T17:15:48.142444'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
