INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (320909, 14194, 'The Guardian', 'en', '‘Absolutely unacceptable’: Japan condemns visit by Vladimir Putin to disputed Kuril Islands', 'https://www.theguardian.com/world/2026/aug/13/japan-condemns-vladimir-putin-visit-kuril-islands', 'Japanese PM says islands seized by Soviets late in second world war are part of her country under international law The Japanese government has reacted angrily to Vladimir Putin’s first visit to the disputed Kuril Islands, which are claimed by both Tokyo and Moscow. Japan’s foreign minister, Toshimitsu Motegi, summoned the Russian ambassador Nikolay Nozdrev, while the prime minister, Sanae Takaichi, called Putin’s actions “absolutely unacceptable”. Continue reading...', 'https://i.guim.co.uk/img/media/6460023264d60122192ce6de3b86eb5f2bdd2623/730_0_5000_4000/master/5000.jpg?width=140&quality=85&auto=format&fit=max&s=8c545016967e6e181924ecebe30c3d11', '2026-08-13T12:56:57+00:00', '2026-08-13T22:50:37.871372'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
