INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321098, 14194, 'France 24', 'en', 'Japan protests Putin''s first visit to disputed islands', 'https://www.france24.com/en/video/20260813-japan-protests-putin-s-first-visit-to-disputed-islands', 'President Vladimir Putin visited Russia''s far-eastern Kuril islands for the first time on Thursday, prompting protests by Japan which also claims the territory.', 'https://s.france24.com/media/display/3c82eb52-9723-11f1-9eed-005056bf30b7/w:1024/p:16x9/EN-20260813-150619-150804-CS.jpg', '2026-08-13T15:06:07+00:00', '2026-08-13T22:50:55.887712'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321106, 14194, 'France 24', 'en', 'Putin visits disputed Kuril Islands', 'https://www.france24.com/en/video/20260813-putin-visits-disputed-kuril-islands-1', '🇷🇺 🇯🇵 Russian President Putin has made his first visit to the disputed Kuril Islands, travelling to Iturup, one of four islands claimed by both Russia and Japan. Tokyo strongly protested the visit, calling it “absolutely unacceptable.”', 'https://s.france24.com/media/display/ad76d1ba-971f-11f1-a8c0-005056bf30b7/w:1024/p:16x9/Putin-visits-disputed-Kuril-islands.jpg', '2026-08-13T14:39:19+00:00', '2026-08-13T22:50:55.960997'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
