INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (322316, 14194, 'The New York Times', 'en', 'Putin Visits Islands Seized From Japan in World War II, Angering Tokyo', 'https://www.nytimes.com/2026/08/13/world/asia/putin-visit-islands-japan-russia.html', 'Prime Minister Sanae Takaichi of Japan has been a public critic of Mr. Putin, who has denounced her country’s sanctions against Russia over the Ukraine war.', 'https://static01.nyt.com/images/2026/08/13/world/asia/Putin-Kuril-Islands-Cover-Image/Putin-Kuril-Islands-Cover-Image-mediumSquareAt3X.jpg', '2026-08-13T22:38:31+00:00', '2026-08-13T22:52:26.732543'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (322388, 14194, 'The Washington Post', 'en', 'Putin angers Japan with visit to islands seized by Soviet Union in WWII', 'https://www.washingtonpost.com/world/2026/08/13/putin-angers-japan-with-visit-islands-seized-by-soviet-union-wwii', 'Prime Minister Sanae Takaichi said the Russian leader''s visit “wounds the feelings” of the Japanese people and further hardens anti-Russian sentiment in her country.', '', '2026-08-13T16:17:42+00:00', '2026-08-13T22:52:42.002175'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
